export const Schema = z.object({
    // ===== 基础属性 =====
    level: z.number().min(1).max(999).default(1),
    exp: z.number().min(0).default(0),
    exp_next: z.number().default(200),
    hp: z.number().min(0).default(500),
    hp_max: z.number().min(1).default(500),
    mp: z.number().min(0).default(500),
    mp_max: z.number().min(1).default(500),
    // ===== 四围属性 =====
    体质: z.number().min(1).max(999).default(10),
    精神: z.number().min(1).max(999).default(10),
    魅力: z.number().min(1).max(999).default(10),
    技巧: z.number().min(1).max(999).default(10),
    // ===== 战斗属性 =====
    atk: z.number().default(100),
    def: z.number().default(100),
    自由属性点: z.number().min(0).default(0),
    技能点: z.number().min(0).default(0),
    // ===== 境界系统 =====
    境界: z.enum(["幻身境", "显身境", "明身境", "真身境", "通神境"]).default("幻身境"),
    神体类型: z.enum(["未觉醒", "阳神", "阴神", "阴阳神"]).default("未觉醒"),
    // ===== 货币 =====
    灵石: z.number().min(0).default(100),
    军功: z.number().min(0).default(0),
    // ===== 宗门声望 =====
    玉足宫声望: z.number().min(-1000).max(5000).default(0),
    百兽御魔宗声望: z.number().min(-1000).max(5000).default(0),
    阴阳门声望: z.number().min(-1000).max(5000).default(0),
    合欢宗声望: z.number().min(-1000).max(5000).default(0),
    欲仙门声望: z.number().min(-1000).max(5000).default(0),
    天魔宗声望: z.number().min(-1000).max(5000).default(0),
    采阴教声望: z.number().min(-1000).max(5000).default(0),
    // ===== 名器持有 =====
    名器: z.array(z.string()).default([]),
    // ===== 技能列表 =====
    技能列表: z.array(z.object({
        name: z.string(),
        type: z.enum(["主动", "被动"]),
        level: z.number().min(1).default(1),
        desc: z.string(),
        cost_mp: z.number().min(0).default(0),
    })).default([]),
    // ===== 装备 =====
    装备: z.array(z.object({
        name: z.string(),
        type: z.enum(["法宝", "服饰", "首饰", "坐骑", "宠物"]),
        rarity: z.enum(["凡品", "灵品", "宝品", "仙品", "圣品"]),
        desc: z.string(),
    })).default([]),
    // ===== 统计数据 =====
    炮友数量: z.number().min(0).default(0),
    击败数量: z.number().min(0).default(0),
    播种总数: z.number().min(0).default(0),
    // ===== 位置/时间 =====
    当前地域: z.string().default("红欲平原"),
    当前城市: z.string().default("云雨城"),
    当前地点: z.string().default("初试云雨台"),
    // ===== 缺失的模板变量 =====
    性癖爱好: z.string().default("未知"),
    性癖厌恶: z.string().default("无"),
    丹药: z.array(z.string()).default([]),
    物品: z.array(z.string()).default([]),
    年: z.number().default(1),
    月: z.number().min(1).max(12).default(1),
    日: z.number().min(1).max(31).default(1),
    时间: z.string().default("辰时"),
    // ===== NPC 关系数据 =====
    NPC_ID: z.string().default(""),
    好感: z.string().default(""),
    关系: z.string().default(""),
    // ===== 阳具/名器 =====
    阳具名器: z.string().default("无"),
    阳具长度: z.string().default("15cm"),
    // ===== 在场NPC =====
    在场NPC: z.string().default("无"),
    // ===== NPC 在场详情 =====
    宗门: z.string().default(""),
    姓名1: z.string().default(""),
    姓名2: z.string().default(""),
    等级: z.number().min(1).max(999).default(1),
    当前行为与状态: z.string().default("待命"),
    当前想法: z.string().default("无"),
});
